def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    hp = float(my_status['hp'])
    budget = float(my_status['budget'])
    no_water_days = int(my_status['no_water_days'])

    alive_opps = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', True):
            alive_opps.append(opp)

    # If we can't win, still try to keep hp from collapsing.
    if not alive_opps:
        return max(0.0, min(budget, DAILY_SALARY * (0.35 if hp > 3 else 0.9)))

    # Read yesterday bids to infer aggressiveness.
    prev_bids = []
    prev_max = 0.0
    prev_min = None
    for opp in alive_opps:
        trace = opp.get('previous_trace', {}) or {}
        bid = trace.get('bid', None)
        if bid is not None:
            try:
                b = float(bid)
            except Exception:
                continue
            prev_bids.append(b)
            if b > prev_max:
                prev_max = b
            if prev_min is None or b < prev_min:
                prev_min = b

    # Aggression signals from yesterday.
    # Cindy: high average bids and survived -> likely bidding high again.
    # Alex: died early after high bids -> may reduce, but we can't rely on it.
    # Use hp/no_water_days to decide urgency.
    urgent = (hp <= 2.5) or (no_water_days >= 2)

    # Supply scaling: when supply is low, water is scarcer -> need stronger bids.
    # Map supply in [15,25] to a multiplier in [1.0, 1.35] for bid pressure.
    if MAX_SUPPLY > MIN_SUPPLY:
        scarcity = (MAX_SUPPLY - supply) / (MAX_SUPPLY - MIN_SUPPLY)
    else:
        scarcity = 0.5
    scarcity = max(0.0, min(1.0, float(scarcity)))
    pressure_mult = 1.0 + 0.35 * scarcity

    # Baseline bid: aim to beat typical mid-range bids without matching top bids.
    # If yesterday's max bid was very high, avoid overpaying; bid around 60-75% of it.
    if prev_bids:
        target = prev_max * (0.68 if not urgent else 0.82)
        # Also ensure we bid at least a fraction of DAILY_SALARY to compete.
        floor_bid = DAILY_SALARY * (0.45 if not urgent else 0.75)
        bid = max(floor_bid, target)
    else:
        bid = DAILY_SALARY * (0.55 if not urgent else 0.8)

    bid *= pressure_mult

    # Cap by budget; also avoid wasting budget when hp is healthy.
    if not urgent and hp > 5:
        bid_cap = DAILY_SALARY * 0.65
    elif not urgent:
        bid_cap = DAILY_SALARY * 0.85
    else:
        bid_cap = DAILY_SALARY * 1.0

    bid = min(bid, bid_cap)
    bid = max(0.0, min(budget, bid))

    # Final safety: if budget is too low, bid whatever remains.
    if budget <= 1.0:
        return max(0.0, budget)

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    # If no opponents are alive, bid minimally to survive and save budget
    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.1)

    # Collect yesterday's bids from alive opponents
    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    highest_prev_bid = 0.0
    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)

    # Determine base bid based on my health and no-water days
    bid_amount = 0.0
    if my_status['hp'] <= 2 or my_status['no_water_days'] > 0:
        # Desperate: Bid very aggressively
        if highest_prev_bid >= DAILY_SALARY * 0.8: # If opponents bid very high (>= 120)
            bid_amount = highest_prev_bid + 5.0
        else:
            bid_amount = DAILY_SALARY * 0.9 # Base 135
    elif my_status['hp'] <= 4:
        # Getting low: Bid moderately aggressively
        if highest_prev_bid >= DAILY_SALARY * 0.6: # If opponents bid high (>= 90)
            bid_amount = max(DAILY_SALARY * 0.7, highest_prev_bid + 2.0) # Base 105 or higher
        else:
            bid_amount = DAILY_SALARY * 0.7 # Base 105
    else:
        # Relatively healthy: Bid competitively
        if highest_prev_bid >= DAILY_SALARY * 0.5: # If opponents bid moderately (>= 75)
            bid_amount = max(DAILY_SALARY * 0.55, highest_prev_bid + 1.0) # Base 82.5 or higher
        else:
            bid_amount = DAILY_SALARY * 0.55 # Base 82.5

    # Further adjust bid based on supply scarcity
    supply = day_context['supply']
    if supply <= WATER_REQ: # Very low supply, only one full water requirement possible
        if my_status['hp'] <= 3 or my_status['no_water_days'] > 0:
            bid_amount = max(bid_amount, DAILY_SALARY * 0.95) # 142.5
        else:
            bid_amount = max(bid_amount, DAILY_SALARY * 0.8) # 120
    elif supply < 2 * WATER_REQ: # Moderate supply, enough for 1-2 agents to get water
        if my_status['hp'] <= 2 or my_status['no_water_days'] > 0:
            bid_amount = max(bid_amount, DAILY_SALARY * 0.9) # 135
        elif my_status['hp'] <= 4:
            bid_amount = max(bid_amount, DAILY_SALARY * 0.75) # 112.5

    # Ensure bid does not exceed budget and has a strategic upper limit
    max_strategic_bid = DAILY_SALARY * 1.1 # Default cap at 110% of salary
    if my_status['hp'] <= 1 or my_status['no_water_days'] >= 2: # Extreme desperation
        max_strategic_bid = DAILY_SALARY * 1.2 # Willing to go up to 120% of salary

    final_bid = min(my_status['budget'], bid_amount, max_strategic_bid)

    # Ensure bid is not negative
    final_bid = max(0.0, final_bid)

    return final_bid

